args<-commandArgs(TRUE);A<-normalizePath(args[1],winslash='/');C<-file.path(A,'02_CONTROLLI');suppressPackageStartupMessages(library(ape));tr<-read.tree(file.path(A,'sources/Lsakei_229.treefile'));N<-length(tr$tip.label)
rd<-function(n,s){p<-list.files(C,pattern=paste0('^Table_S',n,'_'),full.names=TRUE);read.delim(file.path(p,paste0(s,'.tsv')),quote='"',check.names=FALSE,stringsAsFactors=FALSE)}
refs<-rd(10,'References_182');samples<-rd(10,'Samples_100');ret<-samples$Sample[samples$Retained_in_tree=='True'];stopifnot(N==229,length(ret)==47,nrow(refs)==182,setequal(tr$tip.label,c(ret,refs$Accession)),!anyDuplicated(tr$tip.label),all(is.finite(tr$edge.length)),all(tr$edge.length>=0))
ch<-split(tr$edge[,2],tr$edge[,1]);tips<-function(v){if(v<=N)return(tr$tip.label[v]);unlist(lapply(ch[[as.character(v)]],tips),use.names=FALSE)}
key<-function(a){a<-sort(a);b<-sort(setdiff(tr$tip.label,a));if(length(a)>length(b)||(length(a)==length(b)&&paste(a,collapse=';')>paste(b,collapse=';')))a<-b;paste(a,collapse=';')}
branches<-do.call(rbind,lapply(which(tr$edge[,2]>N),function(i){v<-tr$edge[i,2];lab<-tr$node.label[v-N];s<-suppressWarnings(as.numeric(strsplit(lab,'/',fixed=TRUE)[[1]]));if(length(s)!=2)s<-c(NA,NA);data.frame(key=key(tips(v)),SH=s[1],UF=s[2])}));bs<-rd(10,'Branch_support');bs$key<-vapply(strsplit(bs$Original_Newick_side_leaves,'; ',fixed=TRUE),key,character(1));ix<-match(branches$key,bs$key);stopifnot(!anyNA(ix),all(is.na(branches$SH)==is.na(bs$SH_aLRT_percent[ix])),all(is.na(branches$UF)==is.na(bs$UFBoot_percent[ix])),max(abs(branches$SH-bs$SH_aLRT_percent[ix]),na.rm=TRUE)<1e-10,max(abs(branches$UF-bs$UFBoot_percent[ix]),na.rm=TRUE)<1e-10)
g<-rd(10,'Group_support');out<-data.frame()
for(i in 1:nrow(g)){leaves<-strsplit(g$Specified_leaves[i],'; ',fixed=TRUE)[[1]];complete<-all(leaves%in%tr$tip.label);exclusive<-complete&&key(leaves)%in%branches$key;stopifnot(complete==(g$Complete_group[i]=='True'),length(intersect(leaves,tr$tip.label))==g$N_retained[i]);if(complete)stopifnot(exclusive==(g$Exclusive_split[i]=='True'));if(exclusive){j<-match(key(leaves),branches$key);stopifnot(abs(branches$SH[j]-g$SH_aLRT_percent[i])<1e-10,abs(branches$UF[j]-g$UFBoot_percent[i])<1e-10)};out<-rbind(out,data.frame(group=g$Specified_group[i],complete=complete,exclusive_split=exclusive,verified=TRUE))}
write.table(out,file.path(C,'TREE_GROUPS_AUDIT.tsv'),sep='\t',row.names=FALSE,quote=TRUE);write.table(data.frame(tips=N,metagenomes=length(ret),references=nrow(refs),internal_bipartitions_verified=nrow(branches),group_screens_verified=nrow(g),Italian_references=sum(refs$Source_geography=='Italy'),nonmissing_supports=sum(!is.na(branches$UF))),file.path(C,'TREE_AUDIT.tsv'),sep='\t',row.names=FALSE,quote=TRUE);cat('TREE_VERIFIED:229 tips;226 branches;14 group screens\n')
